useEffect(() => {
  if (!driverLocationMarker) {
    setRoadNetworkSnap(null)
    return
  }

  const controller = new AbortController()
  const timeout = window.setTimeout(() => controller.abort(), 6000)

  const fetchNearestRoad = async () => {
    try {
      const response = await fetch(
        `https://router.project-osrm.org/nearest/v1/driving/${driverLocationMarker.lng},${driverLocationMarker.lat}`,
        { signal: controller.signal }
      )
      const payload = await response.json()
      if (payload?.code === 'Ok' && payload?.waypoints?.[0]) {
        const waypoint = payload.waypoints[0]
        const snapLat = waypoint.location[1]
        const snapLng = waypoint.location[0]
        const distance = waypoint.distance
        setRoadNetworkSnap({
          lat: snapLat,
          lng: snapLng,
          distanceMeters: distance,
        })
      }
    } catch {
      // Keep previous snap or let it fallback
    }
  }

  void fetchNearestRoad()

  return () => {
    window.clearTimeout(timeout)
    controller.abort()
  }
}, [driverLocationMarker?.lat, driverLocationMarker?.lng])

// Snap the driver marker onto the drawn road route (render-only). The raw
// driverLocationMarker is intentionally left untouched so route/ETA requests
// keep keying off the true GPS origin and never loop through the snapped point.
const roadSnap = useMemo(() => {
  if (!driverLocationMarker) return null
  const roadPolyline: [number, number][] = [...completedRouteGeometry, ...routeGeometry]
  const result = projectPointOntoPolyline(
    { lat: driverLocationMarker.lat, lng: driverLocationMarker.lng },
    roadPolyline
  )
  if (!result || result.distanceMeters > SNAP_MAX_METERS) return null
  return result
}, [driverLocationMarker?.lat, driverLocationMarker?.lng, routeGeometry, completedRouteGeometry])

const renderedDriverMarker = useMemo(() => {
  if (!driverLocationMarker) return null
  if (roadSnap) {
    return { ...driverLocationMarker, lat: roadSnap.point.lat, lng: roadSnap.point.lng }
  }
  if (roadNetworkSnap) {
    return { ...driverLocationMarker, lat: roadNetworkSnap.lat, lng: roadNetworkSnap.lng }
  }
  return driverLocationMarker
}, [driverLocationMarker, roadSnap, roadNetworkSnap])

const snapDistance = roadSnap ? roadSnap.distanceMeters : (roadNetworkSnap ? roadNetworkSnap.distanceMeters : 0)

// Small dot marking the real GPS reading, shown only when the driver is
// visibly off the road after snapping.
const actualLocationDot =
  driverLocationMarker && snapDistance >= ACTUAL_HINT_MIN_METERS
    ? {
        id: `driver-${trip.id}-actual`,
        driverName: 'Actual GPS location',
        vehiclePlate: '',
        lat: driverLocationMarker.lat,
        lng: driverLocationMarker.lng,
        status: '',
        markerType: 'dot' as const,
        markerColor: '#94a3b8',
      }
    : null

