import { execSync } from 'child_process';
import * as fs from 'fs';
import * as path from 'path';

export const dynamic = 'force-dynamic';

export default function RestorePage() {
  let result = '';
  try {
    // Get all dangling blobs
    const fsckOut = execSync('git fsck --lost-found', { encoding: 'utf-8' });
    const blobs = fsckOut
      .split('\n')
      .filter((line) => line.includes('dangling blob'))
      .map((line) => line.split(' ')[2].trim());

    result += `Found ${blobs.length} dangling blobs. Scanning...\n`;

    let foundBlob: string | null = null;
    let foundContent: string | null = null;

    for (const blob of blobs) {
      try {
        const content = execSync(`git cat-file -p ${blob}`, {
          encoding: 'utf-8',
          maxBuffer: 10 * 1024 * 1024,
        });

        if (
          content.includes('renderedDriverMarker') &&
          content.includes('ACTUAL_HINT_MIN_METERS') &&
          content.length > 100000
        ) {
          foundBlob = blob;
          foundContent = content;
          result += `Match found in blob: ${blob} (Size: ${content.length} characters)\n`;
          break;
        }
      } catch (e: any) {
        // Skip
      }
    }

    if (foundBlob && foundContent) {
      const targetPath = path.join(process.cwd(), 'src/components/portals/driver/sections/trips/trip-detail-view.tsx');
      fs.writeFileSync(targetPath, foundContent, 'utf-8');
      result += `Successfully restored trip-detail-view.tsx from blob ${foundBlob}!\n`;
    } else {
      result += `No matching dangling blobs found.\n`;
    }
  } catch (error: any) {
    result += `Error: ${error.message}\n`;
  }

  return (
    <div style={{ padding: '2rem', fontFamily: 'sans-serif' }}>
      <h1>Blob Scanning and Recovery</h1>
      <pre style={{ background: '#f5f5f5', padding: '1rem', borderRadius: '4px' }}>{result}</pre>
    </div>
  );
}

