  let result = '';
  try {
    const fsckOut = execSync('git fsck --lost-found', { encoding: 'utf-8' });
    const blobs = fsckOut
      .split('\n')
      .filter((line) => line.includes('dangling blob'))
      .map((line) => line.split(' ')[2].trim());

    result += `Found ${blobs.length} dangling blobs.\n`;

    if (blobs.length === 0) {
      return (
        <div style={{ padding: '2rem', fontFamily: 'sans-serif' }}>
          <h1>Blob Recovery</h1>
          <pre>{result}No dangling blobs found.</pre>
        </div>
      );
    }

    // Batch check sizes
    const batchInput = blobs.join('\n') + '\n';
    const batchOutput = execSync('git cat-file --batch-check', {
      input: batchInput,
      encoding: 'utf-8',
    });

    const candidateBlobs: string[] = [];
    const lines = batchOutput.split('\n');
    for (const line of lines) {
      const trimmed = line.trim();
      if (!trimmed) continue;
      const parts = trimmed.split(' ');
      if (parts.length >= 3) {
        const hash = parts[0];
        const type = parts[1];
        const size = parseInt(parts[2], 10);
        // Original trip-detail-view.tsx is ~130KB. Look for blobs between 100KB and 200KB.
        if (type === 'blob' && size > 100000 && size < 200000) {
          candidateBlobs.push(hash);
        }
      }
    }

    result += `Found ${candidateBlobs.length} candidate blobs matching size constraints (100KB-200KB).\n`;

    let foundBlob: string | null = null;
    let foundContent: string | null = null;

    for (const blob of candidateBlobs) {
      try {
        const content = execSync(`git cat-file -p ${blob}`, {
          encoding: 'utf-8',
          maxBuffer: 10 * 1024 * 1024,
        });

        if (
          content.includes('renderedDriverMarker') &&
          content.includes('ACTUAL_HINT_MIN_METERS')
        ) {
          foundBlob = blob;
          foundContent = content;
          result += `Match found in blob: ${blob} (Size: ${content.length} characters)\n`;
          break;
        }
      } catch (e: any) {
        result += `Error reading blob ${blob}: ${e.message}\n`;
      }
    }

    if (foundBlob && foundContent) {
      const targetPath = path.join(process.cwd(), 'src/components/portals/driver/sections/trips/trip-detail-view.tsx');
      fs.writeFileSync(targetPath, foundContent, 'utf-8');
      result += `Successfully restored trip-detail-view.tsx from blob ${foundBlob}!\n`;
    } else {
      result += `No matching dangling blobs found.\n`;
    }
  } catch (error: any) {
    result += `Error: ${error.message}\n`;
  }

  return (
    <div style={{ padding: '2rem', fontFamily: 'sans-serif' }}>
      <h1>Blob Scanning and Recovery (Optimized)</h1>
      <pre style={{ background: '#f5f5f5', padding: '1rem', borderRadius: '4px' }}>{result}</pre>
    </div>
  );
}

